local config = {
  ui_story_30360401_1_dialog_content = "Entonces... ¿Qué pasa?",
  ui_story_30360401_2_dialog_content = "<color=#e8d9bb>Después de que cayó la oscuridad, cerré los ojos y caí en un sueño profundo.</color>",
  ui_story_30360401_3_dialog_content = "Pero me desperté en medio de la noche con un par de ojos brillando en la oscuridad...",
  ui_story_30360401_4_dialog_content = "Estaba seguro de que lo que estaba frente a mí era una bestia...",
  ui_story_30360401_5_dialog_content = "¿Quieres decir, un lobo te estaba observando anoche?",
  ui_story_30360401_6_dialog_content = "Sí, creo que puede ser uno de tus lobos de sombra.",
  ui_story_30360401_7_dialog_content = "Eso es imposible... No he usado mi magia de sombras, ni he ordenado a ninguno de mis lobos de sombra que lo hagan.",
  ui_story_30360401_8_dialog_content = "Lo sé... No estoy dudando de ti.",
  ui_story_30360401_9_dialog_content = "Pero esto ha estado sucediendo durante tantos días que tengo que hablar contigo al respecto.",
  ui_story_30360401_10_option_content = "Aunque no tengo pruebas...",
  ui_story_30360401_11_dialog_content = "Porque podía sentirlo.",
  ui_story_30360401_12_dialog_content = "¿Quieres decir, a través de tu habilidad psíquica?",
  ui_story_30360401_13_dialog_content = "Bueno, entonces podrían ser ellos.",
  ui_story_30360401_14_option_content = "Estoy seguro de que era un lobo sombrío.",
  ui_story_30360401_15_dialog_content = "¿Es posible que actúen sin tu permiso? ¿Podrían estar vagando libremente mientras descansas?",
  ui_story_30360401_16_dialog_content = "No lo sé... ¿Quizás?",
  ui_story_30360401_17_dialog_content = "Oye, ¿por qué fuiste a la habitación de PlayerName anoche?",
  ui_story_30360401_18_dialog_content = "<color=#e8d9bb>Los lobos sombríos encogen sus orejas.</color>",
  ui_story_30360401_19_dialog_content = "Parece que tenías razón.",
  ui_story_30360401_20_dialog_content = "Como sabes eso?",
  ui_story_30360401_21_dialog_content = "Solo puedo notarlo por sus reacciones físicas, como la forma en que se movían sus orejas.",
  ui_story_30360401_22_dialog_content = "Después de todo, no soy como tú. No puedo hablar con los animales.",
  ui_story_30360401_23_dialog_content = "No, no, realmente no es así... Además, ¿cuentan como animales...?",
  ui_story_30360401_24_dialog_content = "De todos modos, ¿puedes vigilar a tus lobos sombríos? Al menos evita que vengan a mi habitación y me miren en medio de la noche.",
  ui_story_30360401_25_dialog_content = "Está bien.",
  ui_story_30360401_26_dialog_content = "Está prohibido que entres a la habitación de PlayerName.",
  ui_story_30360401_27_dialog_content = "<color=#e8d9bb>Los lobos sombríos no muestran ninguna reacción.</color>",
  ui_story_30360401_28_dialog_content = "Se desconectaron.",
  ui_story_30360401_29_option_content = "Espera... ¿Por qué?",
  ui_story_30360401_30_dialog_content = "¿Cómo debería saberlo? Probablemente tienen sus propias razones.",
  ui_story_30360401_31_dialog_content = "¿Eso significa que seguirán viniendo a mi habitación para mirarme en medio de la noche?",
  ui_story_30360401_32_dialog_content = "Más probable.",
  ui_story_30360401_33_dialog_content = "Eso es preocupante... ¿Cómo puedo dormir si es así?",
  ui_story_30360401_32_option_content = "¡No, no... Tienes que convencerlos!",
  ui_story_30360401_35_dialog_content = "¿Cómo puedo convencerlos?",
  ui_story_30360401_36_dialog_content = "¿Por qué me preguntas? ¿No eres su amo?",
  ui_story_30360401_37_dialog_content = "No he logrado enseñarles ningún comando aparte de atacar. Si no me escuchan en absoluto, no hay nada que pueda hacer.",
  ui_story_30360401_38_dialog_content = "¿Qué debo hacer?",
  ui_story_30360401_39_dialog_content = "¿No puedes conectarte con ellos psíquicamente? Intenta comunicarte con ellos.",
  ui_story_30360401_40_option_content = "Es un poco desalentador.",
  ui_story_30360401_41_dialog_content = "¿Cómo es intimidante?",
  ui_story_30360401_42_dialog_content = "Parecen bestias misteriosas, y están registradas en la base de datos del Coloso como criaturas peligrosas, sin mencionar el hecho de que nacen de tus habilidades.",
  ui_story_30360401_43_dialog_content = "Si se pueden considerar como entidades psíquicamente viables aún es desconocido para mí. No estoy seguro de si puedo comunicarme con ellos.",
  ui_story_30360401_44_dialog_content = "Recogí la habilidad del Lobo Sombrío de unas ruinas desconocidas. Ni siquiera sé qué son...",
  ui_story_30360401_45_dialog_content = "Puedes considerarlos como criaturas mágicas, pero para mí son como perros ordinarios.",
  ui_story_30360401_46_option_content = "Estoy seguro de que estará bien solo intentarlo...",
  ui_story_30360401_47_dialog_content = "Parecen perros lindos, aunque no se ven exactamente igual a los registrados en la base de datos de Soroz.",
  ui_story_30360401_48_dialog_content = "<color=#e8d9bb>Los lobos sombríos comienzan a mostrar sus dientes.</color>",
  ui_story_30360401_49_dialog_content = "¡Ten cuidado! Mantén tu distancia... Se están volviendo inquietos.",
  ui_story_30360401_50_dialog_content = "No los toques tan repentinamente. Aunque se les llame Lobos Sombríos, aún no sabemos exactamente de dónde vienen estas criaturas mágicas.",
  ui_story_30360401_51_dialog_content = "No hagas nada para provocarlos, o pueden atacarte.",
  ui_story_30360401_52_dialog_content = "Espera un minuto. Esta es tu habilidad, ¿y eso es todo lo que tienes que decir sobre ellos?",
  ui_story_30360401_53_dialog_content = "Adquirí esta habilidad pero no la he estudiado profundamente. Todo lo que sé es que puedo usarla.",
  ui_story_30360401_54_dialog_content = "Entonces, será mejor que mantenga mi distancia.",
  ui_story_30360401_55_dialog_content = "<color=#e8d9bb>Cierras los ojos de nuevo y vuelves a la oscuridad, bloqueando las interferencias externas. Luego, comienzas a concentrarte...</color>",
  ui_story_30360401_56_dialog_content = "Aunque puedo usar mi habilidad psíquica en ellos, aún no puedo iniciar una conversación, como era de esperar...",
  ui_story_30360401_57_dialog_content = "¡Espera... De repente estoy sintiendo una imagen!",
  ui_story_30360401_58_dialog_content = "Es un lobo sombrío... No, hay más de uno...",
  ui_story_30360401_59_dialog_content = "¡Eso parece un Hydrad entre ellos!",
  ui_story_30360401_60_dialog_content = "¿¡También has estado en mi habitación!?",
  ui_story_30360401_61_dialog_content = "...",
  ui_story_30360401_62_dialog_content = "¡Di algo!",
  ui_story_30360401_63_dialog_content = "Has respondido a todas mis preguntas hasta ahora. \n¿No sientes que eres obviamente culpable?",
  ui_story_30360401_64_dialog_content = "Por favor, ayúdame a entender qué está pasando aquí.",
  ui_story_30360401_65_dialog_content = "Hmm... Sí, fui a tu habitación. ¿Y qué?",
  ui_story_30360401_66_dialog_content = "¡Eres el responsable de todo esto y ni siquiera te sientes culpable!?",
  ui_story_30360401_67_dialog_content = "¿Por qué dijiste que era imposible hace un momento? ¿Estás tratando de engañarme culpando a los lobos de sombra?",
  ui_story_30360401_68_dialog_content = "¿Pensaste que podrías ocultarme la verdad fingiendo ayudar a resolver el problema?",
  ui_story_30360401_69_dialog_content = "¡En cuanto lo sentí, lo sabía!",
  ui_story_30360401_70_dialog_content = "No, te lo dije... No fui yo anoche. ¡Solo he estado en tu habitación una vez!",
  ui_story_30360401_71_dialog_content = "¿También puedes ver eso?",
  ui_story_30360401_72_dialog_content = "¿Por qué? ¿Cuándo fuiste allí?",
  ui_story_30360401_73_dialog_content = "Solo el día que llegué por primera vez al Coloso. Fui a observarte.",
  ui_story_30360401_74_dialog_content = "La razón es muy sencilla. Como decidí acompañarte, pensé que al menos debería saber qué eres.",
  ui_story_30360401_75_dialog_content = "Espera... Mi instinto me dice que la razón por la que están actuando por su propia voluntad eres tú.",
  ui_story_30360401_76_dialog_content = "¿Algo te ha estado molestando recientemente?",
  ui_story_30360401_77_dialog_content = "¿Has oído estas palabras: \"La sombra te está mirando\"?",
  ui_story_30360401_78_option_content = "Sí.",
  ui_story_30360401_79_dialog_content = "¿Se han estado difundiendo estas palabras en Umbraton? Recuerdo que algunas personas de Umbraton hablaron de ello una vez.",
  ui_story_30360401_80_dialog_content = "Bueno, deberías prestarle un poco más de atención.",
  ui_story_30360401_81_dialog_content = "Si puedes ver la verdad a través de la niebla, quiero decir.",
  ui_story_30360401_82_option_content = "No he podido.",
  ui_story_30360401_83_dialog_content = "Esas palabras que circulan por Umbraton son más que un simple rumor mundano. Ve y pregunta a más personas y lo sabrás.",
  ui_story_30360401_84_dialog_content = "Entonces, ¿qué tiene esto que ver con algo?",
  ui_story_30360401_85_dialog_content = "No puedo describirlo para ti. Eres el clarividente. Tienes que verlo por ti mismo.",
  ui_story_30360401_86_dialog_content = "Todo lo que puedo decirte es que las sombras te prestan atención porque les gusta tu olor.",
  ui_story_30360401_87_dialog_content = "No solo los lobos sombríos... Vendrán muchos más.",
  ui_story_30360401_88_dialog_content = "Espera, ¿quieres decir... Los lobos sombríos todavía vendrán a mi habitación?",
  ui_story_30360401_89_dialog_content = "Y que vendrán más criaturas...",
  ui_story_30360401_90_dialog_content = "Más probable.",
  ui_story_30360401_91_dialog_content = "Te acostumbrarás en los próximos días. Los lobos sombríos pronto se irán una vez que se cansen de vigilarte.",
  ui_story_30360401_92_dialog_content = "Eso no servirá. Ya es demasiado para soportar, y probablemente solo vaya a empeorar.",
  ui_story_30360401_93_dialog_content = "¿Por qué?",
  ui_story_30360401_94_dialog_content = "¿Cómo... Cómo logras darle la vuelta a esta conversación de repente!?",
  ui_story_30360401_95_dialog_content = "Si esos animales salvajes insisten en observarme mientras duermo, por supuesto, estoy destinado a sentir miedo.",
  ui_story_30360401_96_dialog_content = "¿Ves a los lobos de sombra como una amenaza para tu seguridad?",
  ui_story_30360401_97_dialog_content = "Quizás.",
  ui_story_30360401_98_dialog_content = "Dada la situación, incluso tú no sabes qué podrían hacer sin tu autorización. ¿Cómo puedes asegurarte de que no me atacarán?",
  ui_story_30360401_99_dialog_content = "Este es un problema serio... Por eso vine a preguntar si podrías ayudar.",
  ui_story_30360401_100_dialog_content = "Solo quieren echar un vistazo más de cerca a lo que eres. Solo piensa en ellos como perros curiosos y estarás bien.",
  ui_story_30360401_101_dialog_content = "Sin embargo, dado que esto te está molestando, no puedo simplemente ignorarlo. Después de todo, en cierta medida, esto es mi culpa.",
  ui_story_30360401_102_dialog_content = "A partir de hoy, los vigilaré por la noche. Si insisten en ir a tu habitación, intentaré detenerlos.",
  ui_story_30360401_103_dialog_content = "Si no puedo detenerlos, iré con ellos.",
  ui_story_30360401_104_dialog_content = "¡Espera! ¿Dónde está la lógica en eso?",
  ui_story_30360401_105_dialog_content = "Si solo los lobos de sombra van a tu habitación, puedes sentirte amenazado. Entonces iré y me aseguraré de que no te hagan nada.",
  ui_story_30360401_106_dialog_content = "No dejaremos que nada más te haga daño.",
  ui_story_30360401_107_dialog_content = "Tus problemas están resueltos. Hecho.",
  ui_story_30360201_X1_dialog_content = "¿De qué están hablando?",
  ui_story_30360201_1_dialog_content = "¿Qué estás haciendo aquí? ¿No fuiste a Lumopolis!?",
  ui_story_30360201_2_dialog_content = "¿Hmm? Yo...",
  ui_story_30360201_3_dialog_content = "Valiente navegante, ¿por qué has venido aquí?",
  ui_story_30360201_4_dialog_content = "Entonces, ¿estás recurriendo a tus viejos trucos de nuevo? ¡Aléjate de PlayerName!",
  ui_story_30360201_5_dialog_content = "¿Qué? ¿Crees que lastimaría a PlayerName?",
  ui_story_30360201_6_dialog_content = "Solo quiero hablar con PlayerName, frente a ti.",
  ui_story_30360201_7_dialog_content = "Imposible. No nos quedaremos aquí y escucharemos tus mentiras.",
  ui_story_30360201_8_dialog_content = "¿Hmm? ¿Por qué no deberíamos escuchar al Sr. Kleken?",
  ui_story_30360201_9_dialog_content = "Serás arrastrado a un abismo de engaño... ¿Crees que solo está jugando contigo?",
  ui_story_30360201_10_dialog_content = "Bueno, me gusta un buen chiste.",
  ui_story_30360201_11_dialog_content = "¿Pero no está Kleken alineado con el Señor Sombrío?",
  ui_story_30360201_12_dialog_content = "Técnicamente, ustedes dos están trabajando juntos, ¿no?",
  ui_story_30360201_13_dialog_content = "Ese no es el problema.",
  ui_story_30360201_14_dialog_content = "Recuerda esto, no siempre puedes creer las palabras de los demás.",
  ui_story_30360201_15_dialog_content = "Si te llevara un charlatán en mi presencia, nunca lo superaría.",
  ui_story_30360201_16_dialog_content = "¿El viaje de Chihiro?",
  ui_story_30360201_17_dialog_content = "Quizás. Eso es lo que supongo, de todos modos.",
  ui_story_30360201_18_dialog_content = "Hmm... ¿De repente me bajas, justo frente a mí? Esto es interesante.",
  ui_story_30360201_19_dialog_content = "¿Sigues aquí?",
  ui_story_30360201_20_dialog_content = "¿Y quieres que me vaya?",
  ui_story_30360201_21_dialog_content = "Bueno, esta es ahora mi sección.",
  ui_story_30360201_22_dialog_content = "Bien, me iré.",
  ui_story_30360201_23_dialog_content = "¿Están las cosas tan mal entre ustedes dos?",
  ui_story_30360201_24_dialog_content = "Solo moderadamente malo.",
  ui_story_30360201_25_dialog_content = "Tengo un poco de curiosidad por saber qué está pasando contigo.",
  ui_story_30360201_26_dialog_content = "Simplemente no tenemos personalidades muy compatibles...",
  ui_story_30360201_27_dialog_content = "<color=#e8d9bb>La primera vez que se vieron en los barrios bajos, las miradas de estos dos sucios niños de la calle no se encontraron y ambos permanecieron en silencio.</color>",
  ui_story_30360201_28_dialog_content = "<color=#e8d9bb>La segunda vez que se vieron en medio del caos del campo de batalla, sus miradas no se encontraron y ambos permanecieron en silencio.</color>",
  ui_story_30360201_29_dialog_content = "<color=#e8d9bb>La tercera vez que se vieron, uno estaba a la izquierda del Señor Sombrío, y el otro a la derecha del Señor Sombrío.</color>",
  ui_story_30360201_30_dialog_content = "<color=#e8d9bb>Uno con una larga túnica, otro con finas prendas, sus miradas no se encontraron y ambos permanecieron en silencio.</color>",
  ui_story_30360201_31_dialog_content = "<color=#e8d9bb>La cuarta vez, la quinta vez... sus miradas no se encontraron y ambos permanecieron en silencio.</color>",
  ui_story_30360201_32_dialog_content = "<color=#e8d9bb>Hasta...</color>",
  ui_story_30360201_33_dialog_content = "Probablemente sea por aquella vez. Déjame contarte.",
  ui_story_30360201_34_dialog_content = "No interrumpas...",
  ui_story_30360201_35_dialog_content = "¿Eh? ¿No te vas?",
  ui_story_30360201_36_dialog_content = "Solo estaba bromeando. En realidad...",
  ui_story_30360201_37_dialog_content = "Déjalo ir. Te lo diré.",
  ui_story_30360201_38_option_content = "Oh, Sr. Kleken, ¿podría irse primero amablemente?",
  ui_story_30360201_39_dialog_content = "Siento que los lobos de sombra ya han mostrado sus dientes, y esto me preocupa...",
  ui_story_30360201_40_dialog_content = "Por supuesto, si insistes, me iré.",
  ui_story_30360201_41_dialog_content = "Perdona mi falta de cortesía. Por favor, continúa.",
  ui_story_30360201_42_option_content = "¿Es eso necesario?...",
  ui_story_30360201_43_dialog_content = "Por supuesto, no es necesario, mi gentil héroe.",
  ui_story_30360201_44_dialog_content = "<color=#e8d9bb>El lobo sombrío junto a Hydrad comienza a gruñir...</color>",
  ui_story_30360201_45_dialog_content = "Tu pequeño lobezno parece enfadado...",
  ui_story_30360201_46_dialog_content = "Deberías salir de aquí antes de que me enoje.",
  ui_story_30360201_47_dialog_content = "No te preocupes, puedo captar una pista.",
  ui_story_30360201_48_dialog_content = "No haré esto más incómodo para PlayerName de lo que ya es. Te veré la próxima vez, héroe.",
  ui_story_30360201_49_dialog_content = "Creo que realmente se ha ido esta vez.",
  ui_story_30360201_50_dialog_content = "¿Pareces algo enojado hoy?",
  ui_story_30360201_51_dialog_content = "¿Por qué has venido aquí de repente? ¿No saliste por negocios?",
  ui_story_30360201_52_dialog_content = "Kleken me pidió que viniera.",
  ui_story_30360201_53_dialog_content = "<size=45>¡Ese tipo otra vez!</size>",
  ui_story_30360201_54_dialog_content = "¿Qué te dijo él?",
  ui_story_30360201_55_dialog_content = "Bueno, él simplemente diría que vayamos a echar un vistazo en otro lugar en ocasiones.",
  ui_story_30360201_56_dialog_content = "Porque mencionó el Coloso esta vez, solo vine a echar un vistazo.",
  ui_story_30360201_57_dialog_content = "Lo siento... Eso suena como una razón bastante confusa, ¿no es así?",
  ui_story_30360201_58_dialog_content = "No... Esa no es la razón.",
  ui_story_30360201_59_dialog_content = "Bueno, volvamos al punto. Entonces, ¿qué pasó entre ustedes dos?",
  ui_story_30360201_60_dialog_content = "¿Siento que estabas recordando tus recuerdos pasados justo ahora?",
  ui_story_30360201_61_dialog_content = "Pero no es nada importante...",
  ui_story_30360201_62_dialog_content = "<color=#e8d9bb>Hasta su primera conversación.</color>",
  ui_story_30360201_63_dialog_content = "¿Buscas al Señor Sombrío? Puede que esté en Lumopolis.",
  ui_story_30360201_64_dialog_content = "¿Estás buscando al Señor Sombrío? Puede que esté en Lumopolis.",
  ui_story_30360201_65_dialog_content = "La primera vez que hablé con él, me mintió.",
  ui_story_30360201_66_dialog_content = "¿Eso es todo? ¿Ese es el final de la historia?",
  ui_story_30360201_67_dialog_content = "Si quieres decir algo, solo escúpelo. No me importará y puedo escucharlo.",
  ui_story_30360201_68_dialog_content = "Lo siento...",
  ui_story_30360201_69_dialog_content = "Ejem... ¿Entonces quieres decir que Kleken te mintió la primera vez que hablaste con él?",
  ui_story_30360201_70_dialog_content = "Sí.",
  ui_story_30360201_71_option_content = "Entonces, ¿el Señor de las Sombras no estaba en Lumopolis ese día?",
  ui_story_30360201_72_dialog_content = "Esperé allí todo el día, hasta que incluso llegaron los guardias.",
  ui_story_30360201_73_dialog_content = "Les di una paliza antes de volver.",
  ui_story_30360201_74_dialog_content = "Más tarde, el Señor de las Sombras me dijo que normalmente no iba a Lumopolis, por lo que fue una mentira completa.",
  ui_story_30360201_75_option_content = "¿Le creíste?",
  ui_story_30360201_76_dialog_content = "Le creí, fui allí y no encontré nada.",
  ui_story_30360201_77_dialog_content = "Entiendo...",
  ui_story_30360201_78_dialog_content = "También golpeé a los Guardias Lumo, causando algunos problemas.",
  ui_story_30360201_79_dialog_content = "Espera... ¿Por qué golpeaste a los guardias?",
  ui_story_30360201_80_dialog_content = "Porque fueron muy groseros conmigo.",
  ui_story_30360201_81_dialog_content = "Ha estado allí agachado con sus perros todo el día...",
  ui_story_30360201_82_dialog_content = "Supongo que va a pedir a los nobles que lo acojan, ¿verdad? Mucha gente está haciendo eso hoy en día...",
  ui_story_30360201_83_dialog_content = "¿Pero también traer a los perros? ¡Eso es pedir un poco demasiado!",
  ui_story_30360201_84_dialog_content = "¡Solo quiero que se callen!",
  ui_story_30360201_85_dialog_content = "Ah, entonces fue culpa de los guardias.",
  ui_story_30360201_86_dialog_content = "Acerca de Kleken mintiéndote...",
  ui_story_30360201_87_option_content = "Quizás eres parcialmente responsable...",
  ui_story_30360201_88_dialog_content = "¿Como... por creer en una mentira tan obvia?",
  ui_story_30360201_89_dialog_content = "Si confiara en ti, ¿sería eso mi culpa?",
  ui_story_30360201_90_dialog_content = "¡Eso no es lo que estoy diciendo!",
  ui_story_30360201_91_dialog_content = "¡Él fue el culpable!",
  ui_story_30360201_92_dialog_content = "Ves, normalmente no creo nada de lo que dice, ¡a menos que sienta la sensación correcta!",
  ui_story_30360201_93_dialog_content = "Aunque eso sonó bastante raro.",
  ui_story_30360201_94_option_content = "¡Fue completamente su culpa!",
  ui_story_30360201_95_dialog_content = "El Sr. Kleken sí que le gusta contar mentiras sin sentido.",
  ui_story_30360201_96_dialog_content = "Se refiere a sí mismo como un estafador, pero también advierte a las personas que no confíen en él.",
  ui_story_30360201_97_dialog_content = "Entonces, no creas nada de lo que dice de nuevo, y toma cada una de sus palabras con pinzas.",
  ui_story_30360201_98_dialog_content = "...",
  ui_story_30360201_99_dialog_content = "¿Q-qué es eso? Tu silencio me está lastimando...",
  ui_story_30360201_100_dialog_content = "Por favor, perdona mi silencio... Es solo que has superado mis expectativas.",
  ui_story_30360201_101_dialog_content = "Inicialmente quería advertirte que no te dejaras engañar por sus palabras.",
  ui_story_30360201_102_dialog_content = "Parece que eres mucho más perceptivo de lo que imaginaba.",
  ui_story_30360201_103_dialog_content = "Gracias por tu preocupación, pero no creo que él me vaya a hacer nada malo.",
  ui_story_30360201_104_dialog_content = "Además, no sé si decir algo así sería un poco entrometido.",
  ui_story_30360201_105_dialog_content = "No quiero que exista ningún conflicto entre aquellos que vienen a vivir a bordo del Colossus.",
  ui_story_30360201_106_dialog_content = "Así que...",
  ui_story_30360201_107_dialog_content = "Lo se.",
  ui_story_30360201_108_dialog_content = "Tienes razón y no eres entrometido. No necesitas dudar de ti mismo.",
  ui_story_30360201_109_dialog_content = "Maravilloso. Entonces, ya que todos estamos trabajando y viviendo juntos en el Coloso, deberíamos intentar llevarnos bien entre nosotros en el futuro!",
  ui_story_30360201_110_dialog_content = "No puedo.",
  ui_story_30360201_111_dialog_content = "Espera... ¿Pensé que acabamos de acordar?",
  ui_story_30360201_112_dialog_content = "No estuve de acuerdo con nada.",
  ui_story_30360201_113_dialog_content = "Ahora que lo pienso, siempre pareces terminar las conversaciones con este tipo de indiferencia dura.",
  ui_story_30360201_114_dialog_content = "Casi me estoy acostumbrando.",
  ui_story_30360201_115_dialog_content = "Debes tener otros asuntos que atender... Yo sé que ciertamente los tengo. Adiós.",
  ui_story_30360201_116_dialog_content = "¿¡Eh!?...",
  ui_story_30360201_117_dialog_content = "¿Qué? ¿Se ha ido?",
  ui_story_30360201_118_dialog_content = "\"Adiós\", ¿eh? Me guste o no, terminaré encontrándome contigo o con ese chico de nuevo.",
  ui_story_30360201_119_dialog_content = "¡De la nada de nuevo!",
  ui_story_30360201_120_dialog_content = "Si una relación está destinada a cambiar, cambiará naturalmente. Si no está destinada a ello, no deberías forzarla.",
  ui_story_30360201_121_dialog_content = "Por ejemplo, las cosas nunca mejorarán entre yo y ese pero.",
  ui_story_30360201_122_dialog_content = "Antes de que llegaras, tuve otra desafortunada conversación con él. Lo que pasó fue...",
  ui_story_30360201_123_dialog_content = "No tú otra vez, pulpo. ¿Has visto...",
  ui_story_30360201_124_dialog_content = "Oh, tal vez puedas encontrar PlayerName en Lumopolis.",
  ui_story_30360201_125_dialog_content = "¿¡Qué dijiste!?",
  ui_story_30360201_126_dialog_content = "¿De qué están hablando?",
  ui_story_30360201_127_dialog_content = "¿Qué estás haciendo aquí? ¿No fuiste a Lumopolis!?",
  ui_story_30360201_128_dialog_content = "Justo como cuando el pulpo sigue siendo tan engañoso como antes...",
  ui_story_30360201_129_dialog_content = "Si no hubieras llegado a tiempo, habría ido a Lumopolis...",
  ui_story_30360601_1_dialog_content = "<color=#e8d9bb>En las sombras de una calle sin nombre se encuentra un oscuro almacén lleno de jaulas de animales. Desde detrás de sus barras brillan innumerables pares de ojos amenazantes.</color>",
  ui_story_30360601_2_dialog_content = "<color=#e8d9bb>Y en las profundidades del almacén, separado por una cortina desgarrada—</color>",
  ui_story_30360601_3_dialog_content = "<color=#e8d9bb>¡Bofetada!</color>",
  ui_story_30360601_4_dialog_content = "...",
  ui_story_30360601_5_dialog_content = "¿Todavía no hablas, eh? Eres difícil de quebrar, te lo concedo.",
  ui_story_30360601_6_dialog_content = "¿Es así como también los tratas?",
  ui_story_30360601_7_dialog_content = "¿Estás bromeando? ¡Estás hablando de mercancía valiosa! ¡Escoria sin valor como tú ni siquiera se compara!",
  ui_story_30360601_8_dialog_content = "\"Mercancía\", ¿eh? Ya veo... Parece que tendré que llevarte ante la justicia después de todo.",
  ui_story_30360601_9_dialog_content = "<color=#e8d9bb>Algún tiempo antes</color>",
  ui_story_30360601_10_dialog_content = "¡Así que realmente eres tú, Hydrad! ¡Hace mucho tiempo que no nos vemos!",
  ui_story_30360601_11_dialog_content = "PlayerName? No podrías haber elegido un peor momento para aparecer.",
  ui_story_30360601_12_dialog_content = "¿Usaste tus habilidades psíquicas para encontrarme? No importa, tengo algo importante que tratar ahora mismo.",
  ui_story_30360601_13_dialog_content = "¿Qué pasa? ¡Guau! ¿Es eso...?",
  ui_story_30360601_14_dialog_content = "Sí. Como puedes ver, es un <color=#FFB400>lobo salvaje</color>.",
  ui_story_30360601_15_dialog_content = "¿Un lobo salvaje? Nunca he visto uno antes... Se parece un poco a tus Lobos Sombríos, ¿no es así?",
  ui_story_30360601_16_dialog_content = "¿De dónde exactamente vienes?",
  ui_story_30360601_17_dialog_content = "¿Yo? Bueno, yo—",
  ui_story_30360601_18_dialog_content = "Me refería al lobo.",
  ui_story_30360601_19_dialog_content = "... Espera, ¿estás comunicándote realmente con un lobo ahora mismo?",
  ui_story_30360601_20_dialog_content = "Por supuesto que no. A diferencia de ti, no puedo hablar con los animales.",
  ui_story_30360601_21_dialog_content = "<color=#e8d9bb>El lobo emite un gruñido desanimado. Aunque sus ojos brillan ferozmente, sus músculos son demasiado débiles para sostener su cuerpo debilitado—</color>",
  ui_story_30360601_22_dialog_content = "Estos chicos son muy perspicaces. Pueden discernir los sentimientos de otras personas, al igual que yo puedo discernir lo que están pensando.",
  ui_story_30360601_23_dialog_content = "Los lobos son animales de manada, pero este está solo, herido y extremadamente desconfiado de mí.",
  ui_story_30360601_24_dialog_content = "Los lobos solitarios no aparecen de la nada en Umbraton. Alguien debe haberlo traído aquí. Salgan, Lobos Sombríos.",
  ui_story_30360601_25_dialog_content = "¿Ves? Estás en buena compañía, ahora deja de ser tan cauteloso conmigo.",
  ui_story_30360601_26_dialog_content = "Necesito que le hagas una pregunta, PlayerName.",
  ui_story_30360601_27_option_content = "¿Qué? ¿Yo?",
  ui_story_30360601_28_dialog_content = "Sí, tú. Solo pregunta qué le pasó.",
  ui_story_30360601_29_option_content = "Lo intentaré, claro...",
  ui_story_30360601_30_dialog_content = "Acércate. No hay nada de qué asustarse.",
  ui_story_30360601_31_dialog_content = "Probablemente este chico tiene amigos por aquí, así que asegúrate de prestar atención a lo que dice.",
  ui_story_30360601_32_dialog_content = "<color=#e8d9bb>Un sucio y deteriorado almacén pasa por la mente del lobo, así como innumerables otros lobos encerrados en jaulas.</color>",
  ui_story_30360601_33_dialog_content = "<color=#e8d9bb>Aparte de esto, una serie de escenas aún más brutales entran en vista—</color>",
  ui_story_30360601_34_dialog_content = "H-Hydrad...",
  ui_story_30360601_35_dialog_content = "¿Qué es? ¿Estás bien?",
  ui_story_30360601_36_dialog_content = "¡Oye! ¡Despierta, PlayerName!",
  ui_story_30360601_37_dialog_content = "E-Estoy bien, solo vi un montón de recuerdos realmente horribles de una vez... Lo siento si te preocupé.",
  ui_story_30360601_38_dialog_content = "No, es mi culpa. No debí haberte pedido que te involucraras cuando solo estabas de paso.",
  ui_story_30360601_39_dialog_content = "¡Está bien, de verdad! Tampoco es la primera vez que esto me sucede...",
  ui_story_30360601_40_dialog_content = "De todos modos, ¡hay cosas más importantes de las que preocuparse! Este lobo necesita nuestra ayuda, Hydrad!",
  ui_story_30360601_41_dialog_content = "Tenías razón. Este lobo y su manada fueron capturados y traídos aquí contra su voluntad, pero este logró escapar.",
  ui_story_30360601_42_dialog_content = "Estaban siendo guardados en algún almacén sucio. Además...",
  ui_story_30360601_43_dialog_content = "Las personas que los mantenían allí eran terribles. No les importaban en absoluto las vidas de estos lobos.",
  ui_story_30360601_44_dialog_content = "... Tengo una idea bastante clara de qué tipo de personas están detrás de esto. Pandillas como la suya fueron enderezadas en el pasado, pero algunas de ellas están tratando de traer de vuelta los viejos tiempos.",
  ui_story_30360601_45_dialog_content = "Y desafortunadamente, siempre habrá personas ricas con mal gusto para financiar sus operaciones.",
  ui_story_30360601_46_dialog_content = "No dejaré que se salgan con la suya esta vez.",
  ui_story_30360601_47_dialog_content = "¿Qué planeas hacer, Hydrad?",
  ui_story_30360601_48_dialog_content = "Dijiste que acabas de ver un montón de recuerdos terribles, ¿verdad? Eso me dice que no hay tiempo que perder si quiero salvar sus vidas.",
  ui_story_30360601_49_dialog_content = "Bien lobo, escucha. Si quieres rescatar a tus amigos, entonces tendrás que trabajar conmigo.",
  ui_story_30360601_50_dialog_content = "Dile que me siga para que pueda ayudarlo.",
  ui_story_30360601_51_dialog_content = "Solo déjamelo a mí.",
  ui_story_30360601_52_dialog_content = "Ahora solo tengo que cambiarme. Dame un minuto.",
  ui_story_30360601_53_dialog_content = "¿Hydrad? Se fue tan rápido... ¿Ya tiene un plan?",
  ui_story_30360601_54_dialog_content = "<color=#e8d9bb>Poco después—</color>",
  ui_story_30360601_55_dialog_content = "He vuelto, ¿ahora qué piensas?",
  ui_story_30360601_56_dialog_content = "Parezco justo como un rico sin cerebro ahora, ¿verdad?",
  ui_story_30360601_57_dialog_content = "Hydrad, tú...",
  ui_story_30360601_58_dialog_content = "¡Te ves tan genial ahora! Eh... quiero decir, ¡aún más genial que antes! En cualquier caso, es completamente diferente a tu estilo habitual.",
  ui_story_30360601_59_dialog_content = "(No estoy seguro de que realmente encaje en la descripción de un \"rico sin cerebro\", pero esto debería servir como disfraz.)",
  ui_story_30360601_60_dialog_content = "Con solo unos pocos toques finales, haré que parezca que soy el dueño de este lobo...",
  ui_story_30360601_61_dialog_content = "Ahí. Una vez que me vean caminando por las calles con eso, estoy seguro de que esas hienas saldrán arrastrándose.",
  ui_story_30360601_62_dialog_content = "Mientras hago eso, necesito que sientas la ubicación de la manada de este lobo, PlayerName.",
  ui_story_30360601_63_dialog_content = "No quiero exponerte a ningún peligro, pero sentir el área no debería ser un problema, ¿verdad?",
  ui_story_30360601_64_dialog_content = "Si me ves yendo a algún lugar con otra persona, alerta al Señor de las Sombras inmediatamente.",
  ui_story_30360601_65_dialog_content = "Estos tipos creen que pueden esconderse de las sombras, pero con tu ayuda, definitivamente los sacaremos a la luz.",
  ui_story_30360601_66_dialog_content = "Prometo que haré lo mejor que pueda, Hydrad.",
  ui_story_30360601_67_dialog_content = "Espera, ¿qué estás—oye!",
  ui_story_30360601_68_dialog_content = "Ahí. Ya pareces una no amenaza, así que solo oculta tu cara con tu sombrero, y nadie te notará.",
  ui_story_30360601_69_dialog_content = "Me voy. El resto está en tus manos ahora.",
  ui_story_30360601_70_dialog_content = "¡O-Okay! No decepciones a Hydrad, no decepciones a Hydrad, no decepciones—",
  ui_story_30360601_71_dialog_content = "¿De qué estás murmurando allí?",
  ui_story_30360601_72_dialog_content = "No importa, es hora de irse.",
  ui_story_30360601_73_dialog_content = "Has pasado por el infierno, ¿no?",
  ui_story_30360601_74_dialog_content = "Awooo—",
  ui_story_30360601_75_dialog_content = "Solo soporta un poco más. Pronto tendrás tu venganza.",
  ui_story_30360601_76_dialog_content = "<color=#e8d9bb>Un rato después—</color>",
  ui_story_30360601_77_dialog_content = "¿Un lobo vivo, eh? Esa es una mascota interesante que tienes ahí, amigo.",
  ui_story_30360601_78_dialog_content = "¿Sí? ¿Y a ti qué?",
  ui_story_30360601_79_dialog_content = "No hace falta ser grosero, ¡amigo! Puedo decir que tienes buen gusto, ¿puedo interesarte en algunas de nuestras novedades?",
  ui_story_30360601_80_dialog_content = "¿Tienes algunos de color sólido? Sus abrigos también deben ser brillantes.",
  ui_story_30360601_81_dialog_content = "Tenía razón, ¡sabes tus cosas! Tenemos todo eso y más, ¡amigo mío!",
  ui_story_30360601_82_dialog_content = "¡Nuestros mejores ejemplares tienen pelajes tan brillantes como el aceite, y son tan feroces como los hay!",
  ui_story_30360601_83_dialog_content = "Tan pronto como los veas, sabrás que son los lobos de combate perfectos. ¡Solo parecen así debido a lo fuertes que son!",
  ui_story_30360601_84_dialog_content = "¿No están preocupados tus gente por el Señor Sombrío?",
  ui_story_30360601_85_dialog_content = "Esos idiotas de Lumopolis son demasiado cobardes para venir aquí solo para comprar animales salvajes, ¿entonces quiénes son exactamente tus clientes?",
  ui_story_30360601_86_dialog_content = "Jajaja, estás haciendo un montón de preguntas, ¡amigo!",
  ui_story_30360601_87_dialog_content = "La única forma de introducir a estos lobos en esta ciudad sin alertar al Gremio Umbraton fue sedándolos durante todo el camino.",
  ui_story_30360601_88_dialog_content = "Je, eso significa que no han comido en días, ¿verdad? Eso no va a hacer ningún favor a sus brillantes abrigos.",
  ui_story_30360601_89_dialog_content = "Oye amigo... ¿Quién eres exactamente tú?",
  ui_story_30360601_90_dialog_content = "Solo alguien que trabaja en un campo similar y muestra interés en tu pequeña operación, eso es todo.",
  ui_story_30360601_91_dialog_content = "Entonces, ¿no planeas comprar ninguno de nuestros lobos?",
  ui_story_30360601_92_dialog_content = "No gracias. Ya tengo suficiente.",
  ui_story_30360601_93_dialog_content = "Tsk, ¿intentando meterse en nuestro negocio, eh? ¿Con quién crees que estás hablando, punk?",
  ui_story_30360601_94_dialog_content = "Siempre es mejor compartir la riqueza, ¿no crees?",
  ui_story_30360601_95_dialog_content = "¿Oíste eso, chicos? ¡Parece que tenemos a un verdadero comediante aquí!",
  ui_story_30360601_96_dialog_content = "Elegiste a las personas equivocadas para meterte hoy, niño. ¡Ahora dime para quién trabajas!",
  ui_story_30360601_97_dialog_content = "Ya es bastante difícil hacer negocios en Umbraton. Con personas como tú, ¿cómo se supone que debemos salir adelante aquí?",
  ui_story_30360601_98_dialog_content = "¿Se supone que me debe importar?",
  ui_story_30360601_99_dialog_content = "¡Rodeenlo! Si no quieres salir herido, te sugiero que vengas en silencio.",
  ui_story_30360601_100_dialog_content = "No quieres morir, ¿verdad?",
  ui_story_30360601_101_dialog_content = "... Bien entonces.",
  ui_story_30360601_102_dialog_content = "<color=#e8d9bb>Los contrabandistas encierran a Hydrad en su almacén, donde permanece durante un tiempo dolorosamente largo.</color>",
  ui_story_30360601_103_dialog_content = "Eres más resistente de lo que pareces, niño. Incluso después de esta paliza, ¿todavía no estás dispuesto a abandonar a tus amigos?",
  ui_story_30360601_104_dialog_content = "¿Quién diablos crees que eres, buscando pelea con nosotros en nuestro territorio...",
  ui_story_30360601_105_dialog_content = "¡Jefe, mira lo que encontramos cuando le quitamos el collar a su lobo! ¡Es el mismo que se escapó antes!",
  ui_story_30360601_106_dialog_content = "¡Maldita sea, sabía que encontrar a este tipo en la calle era demasiado bueno para ser verdad!",
  ui_story_30360601_107_dialog_content = "¿Es esto todo lo que son? Tampoco hay muchos lobos aquí... ¿Es esto realmente todo tu \"mercancía\" también?",
  ui_story_30360601_108_dialog_content = "Si es así, te sugiero que te rindas antes de que mi amigo decida aparecer.",
  ui_story_30360601_109_dialog_content = "¿Tienes un deseo de muerte, amigo? Deberías saber que los <color=#FFB400>Spearows</color> nos permiten llevar a cabo nuestra operación en su territorio, y—",
  ui_story_30360601_110_dialog_content = "¡Silencio, idiota! ¡Se supone que debemos interrogarlo!",
  ui_story_30360601_111_dialog_content = "Maldita sea, entonces parece que tendremos que dejar de jugar.",
  ui_story_30360601_112_dialog_content = "Guárdalo. No me parezco en nada a ustedes, bufones.",
  ui_story_30360601_113_dialog_content = "Eso es porque confío en ese chico... mi amigo, eso es.",
  ui_story_30360601_114_dialog_content = "¿Qué está pasando?",
  ui_story_30360601_115_dialog_content = "¡Estamos jodidos, jefe! El Señor de las Sombras está aquí, y también su gente...",
  ui_story_30360601_116_dialog_content = "¿Q-Qué?",
  ui_story_30360601_117_dialog_content = "Jeje, les tomó bastante tiempo.",
  ui_story_30360601_118_dialog_content = "¡Olvídate de este tipo, jefe! ¡Todavía podemos escapar por la puerta trasera!",
  ui_story_30360601_119_dialog_content = "De ninguna manera.",
  ui_story_30360601_120_dialog_content = "¡Estoy harto de esperar, salgan, Shadow Wolves!",
  ui_story_30360601_121_dialog_content = "¿De dónde vienen estas cosas?",
  ui_story_30360601_122_dialog_content = "¡Cuidado, jefe! ¡El niño logró liberarse!",
  ui_story_30360601_123_dialog_content = "Ahora es el momento de una lección de dolor, y los <color=#FFB400>lobos</color> te la van a enseñar!",
  ui_story_30360601_124_dialog_content = "¡S-Quédate atrás!",
  ui_story_30360601_125_dialog_content = "¡Jefe!",
  ui_story_30360601_126_dialog_content = "Será mejor que termine esto antes de que llegue PlayerName. No quiero que vea lo que está a punto de suceder.",
  ui_story_30360601_127_dialog_content = "<color=#e8d9bb>Algún tiempo después.</color>",
  ui_story_30360601_128_dialog_content = "Gracias de nuevo por tu ayuda.",
  ui_story_30360601_129_option_content = "No lo menciones. Ni siquiera entré antes de que me dijeran que ya se había terminado.",
  ui_story_30360601_130_dialog_content = "¿De veras? Eso es bueno.",
  ui_story_30360601_131_option_content = "No sé, simplemente siento que no hice mucho.",
  ui_story_30360601_132_dialog_content = "Sin ti, este plan nunca habría funcionado.",
  ui_story_30360601_133_dialog_content = "Tenían números, así como una ruta de escape.",
  ui_story_30360601_134_dialog_content = "Porque tú llevaste al Señor Sombrío aquí, pudimos atraparlos a todos en un solo lugar.",
  ui_story_30360601_135_dialog_content = "Oh, jejeje... Estoy bastante seguro de que solo me estás halagando, ¡pero me alegra haber podido ayudar!",
  ui_story_30360601_136_dialog_content = "No, definitivamente eres digno de mi confianza. De hecho, la presencia de tu sombra ahora me combina aún mejor.",
  ui_story_30360601_137_dialog_content = "Por cierto, ese lobo de antes se reunió con su manada y pronto serán enviados de vuelta a su hogar.",
  ui_story_30360601_138_dialog_content = "Después de todo, siempre es mejor que los animales de manada permanezcan juntos.",
  ui_story_30360601_139_dialog_content = "Eso también va para ti, Hydrad. ¡Tú y el Señor de las Sombras hacen un excelente equipo!",
  ui_story_30360601_140_dialog_content = "... De todos modos, me pregunto qué pasará con el resto de los Spearows que estaban involucrados en esta red de contrabando.",
  ui_story_30360601_141_dialog_content = "Ese apestoso pulpo está a cargo de lidiar con ellos, así que quién sabe cuándo se harán las cosas?",
  ui_story_30360601_142_dialog_content = "Pero eso no importa ahora. Vamos, vámonos.",
  ui_story_30360601_143_dialog_content = "¿Eh? ¿A dónde vamos?",
  ui_story_30360601_144_dialog_content = "Estabas haciendo algo antes de que nos encontráramos, ¿verdad? Estaba demasiado ocupado con este asunto del lobo para escucharte.",
  ui_story_30360601_145_dialog_content = "Me ayudaste, así que ahora es mi turno de ayudarte.",
  ui_story_30360601_146_dialog_content = "Ahora vamos. Lo que sea que necesites hacer, estaré allí para echarte una mano.",
  ui_story_30360601_147_dialog_content = "Entonces, ¿cuál es el plan?"
}
return config
